/* Literal uploaded workbook lookup. Symbol interpretation is intentionally not inferred. */
(function(root){'use strict';const byKey=new Map(),data=root.KPVedicWorkbookData;if(!data?.metadata||data.cells?.length!==1296)throw Error('The Vedic matchmaking workbook is incomplete.');
for(const row of data.cells){if(byKey.has(row.key))throw Error('Duplicate workbook lookup key.');byKey.set(row.key,row);}
const clone=x=>JSON.parse(JSON.stringify(x)),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function moon(longitude){if(typeof longitude!=='number'||!Number.isFinite(longitude)||longitude<0||longitude>=360)throw Error('Moon longitude must be in [0,360).');return {sign:Math.floor(longitude/30),nakshatra:Math.min(26,Math.floor(longitude*3/40+1e-12))+1,pada:Math.min(107,Math.floor(longitude*3/10+1e-12))%4+1};}
const NADIS=[0,1,2,2,1,0,0,1,2,2,1,0,0,1,2,2,1,0,0,1,2,2,1,0,0,1,2];
function nadi(groom,bride){const table=data.nadi;if(!table)return {status:'unavailable'};
 const find=p=>table.groups.find(g=>g.entries.some(e=>e.nakshatra===p.nakshatra&&e.pada===p.pada));
 const g=find(groom),b=find(bride);if(!g||!b)throw Error('Missing Nadi pada entry');
 const sameNadi=NADIS[groom.nakshatra-1]===NADIS[bride.nakshatra-1],vedha=g.row===b.row;
 return {status:!sameNadi?'not-applicable':vedha?'retained':'cancelled',sameNadi,vedha,groomRow:g.row,brideRow:b.row,source:{filename:table.filename,sha256:table.sha256,sheet:table.sheet}};}
function nadiHtml(n){if(!n||n.status==='unavailable')return '';const message=n.status==='cancelled'?'नाडी दोष परिहार · Nadi dosha cancelled':n.status==='retained'?'नाडीपादवेध कायम · Nadi dosha retained':'भिन्न नाडी · No same-Nadi dosha';return '<tr><th>नाडीपादवेध</th><td>'+esc(message)+'<br>'+esc(n.source.filename)+' · वर ओळ '+n.groomRow+' / वधू ओळ '+n.brideRow+'<br>एकाच आडव्या ओळीत वेध; समान नाडीतील भिन्न ओळीत परिहार. मूळ गुण व दोष संकेत जतन केले आहेत.</td></tr>';}
function score(groomLongitude,brideLongitude){const groom=moon(groomLongitude),bride=moon(brideLongitude),key=bride.sign+':'+bride.nakshatra+'|'+groom.sign+':'+groom.nakshatra,row=byKey.get(key);if(!row||!row.bride.padas.includes(bride.pada)||!row.groom.padas.includes(groom.pada))throw Error('The workbook has no entry for the actual Moon sign/nakshatra/pada.');return {nadi:nadi(groom,bride),ready:true,method:'Uploaded Vedic workbook',total:row.score,maximum:36,marker:row.marker,defects:[...row.defects],defectText:row.defectText,bride:{...clone(row.bride),pada:bride.pada},groom:{...clone(row.groom),pada:groom.pada},source:{filename:data.metadata.filename,sha256:data.metadata.sha256,sheet:row.sheet,row:row.row,review:row.review},symbolic:row.score===null};}
function totalText(d){return Number.isFinite(d?.total)?d.total+' / 36':(d?.marker||'—')+' · गुण रिकामे';}
function percentText(d){return Number.isFinite(d?.total)?(d.total/36*100).toFixed(1)+'%':'चिन्हासाठी संख्यात्मक गुण दिलेले नाहीत';}
function html(d){if(!d?.ready)return '';const position=p=>esc(p.signName+' · '+p.starLabel)+' · चरण '+p.pada+' (छापील गट '+p.padas.join(', ')+')';return '<section class="mm-workbook-score" data-no-localize><h3>वैदिक गुणमेलन · Uploaded Excel</h3><p><strong>'+esc(totalText(d))+'</strong></p><table class="kp-feature-table"><tbody><tr><th>वर · स्तंभ</th><td>'+position(d.groom)+'</td></tr><tr><th>वधू · पंक्ती</th><td>'+position(d.bride)+'</td></tr><tr><th>मूळ चिन्ह</th><td>'+esc(d.marker||'—')+'</td></tr><tr><th>दोष संकेत</th><td>'+esc(d.defectText||'—')+(d.defects.length?' · स्वतंत्र अंक: '+d.defects.join(', '):'')+'</td></tr>'+nadiHtml(d.nadi)+'<tr><th>स्रोत</th><td>'+esc(d.source.filename+' · '+d.source.sheet+' · पंक्ती '+d.source.row)+'</td></tr></tbody></table><p>स्रोत पडताळणी नोंद: '+esc(d.source.review||'—')+'</p>'+(d.symbolic?'<p>Excel मधील गुण रिकामे आहेत. ★ किंवा X चा संख्यात्मक अर्थ अथवा अपवाद गृहीत धरलेला नाही.</p>':'')+'<p>॥ चे अर्धा गुण हे रूपांतर Excel मध्ये दिल्याप्रमाणे घेतले आहे. इतर दोष संकेतांचे अर्थ व विवाहाचा अंतिम निर्णय गृहीत धरलेला नाही.</p></section>';}
const api=Object.freeze({score,moon,totalText,percentText,html,metadata:()=>clone(data.metadata)});root.KPVedicWorkbook=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window==='undefined'?globalThis:window);
